#include <vector>
#include <algorithm>

class Solution {
public:
    int numTimesAllBlue(std::vector<int>& flips) {
        int maxIdx = 0, count = 0;
        for (int i = 0; i < (int)flips.size(); ++i) {
            maxIdx = std::max(maxIdx, flips[i]);
            if (maxIdx == i + 1) count++;
        }
        return count;
    }
};

class Solution {
    public int numTimesAllBlue(int[] flips) {
        int maxIdx = 0, count = 0;
        for (int i = 0; i < flips.length; i++) {
            maxIdx = Math.max(maxIdx, flips[i]);
            if (maxIdx == i + 1) count++;
        }
        return count;
    }
}

var numTimesAllBlue = function(flips) {
    let maxIdx = 0, count = 0;
    for (let i = 0; i < flips.length; i++) {
        maxIdx = Math.max(maxIdx, flips[i]);
        if (maxIdx === i + 1) count++;
    }
    return count;
};
